 32	\section{The Jacobian as an abelian variety}
 33	
 34	\begin{definition}[Jacobian]
 35	  \label{def:jacobian}
 36	  \lean{AlgebraicGeometry.Jacobian}
 37	  The \emph{Jacobian} \(\Jac(C)\) of a smooth proper curve \(C\) over \(k\) is the identity
 38	  component \(\Pic^0_{C/k}\) of the relative Picard scheme of \(C\) over \(k\): the \(k\)-scheme
 39	  representing (the fppf-sheafification of) the functor of degree-zero line bundles on \(C\).
 40	\end{definition}
 41	
 42	\begin{proposition}[Group scheme structure]
 43	  \label{prop:jacobian_grpobj}
 44	  \uses{def:jacobian}
 45	  \lean{AlgebraicGeometry.Jacobian.instGrpObj}
 46	  \(\Jac(C)\) is a commutative group scheme over \(k\), with multiplication induced by the tensor
 47	  product of line bundles.
 48	\end{proposition}
 84	\begin{lemma}[Base point maps to the origin]
 85	  \label{lem:comp_ofCurve}
 86	  \uses{def:ofCurve, prop:jacobian_grpobj}
 87	  \lean{AlgebraicGeometry.Jacobian.comp_ofCurve}
 88	  The Abel--Jacobi map \(\varphi_P\) sends the base point \(P\) to the neutral element of
 89	  \(\Jac(C)\): \(\varphi_P \circ P = 0\).
 90	\end{lemma}
 91	
 92	\begin{theorem}[Universal property of the Jacobian]
 93	  \label{thm:exists_unique_ofCurve_comp}
 94	  \uses{def:ofCurve, lem:comp_ofCurve, prop:jacobian_grpobj}
 95	  \lean{AlgebraicGeometry.Jacobian.exists_unique_ofCurve_comp}
 96	  \source{abelian-varieties:page-0110}
 97	  \(\Jac(C)\) is the Albanese variety of \(C\): for every abelian variety \(A\) over \(k\) and every
 98	  morphism \(f : C \to A\) with \(f \circ P = 0\), there is a unique homomorphism of group schemes
 99	  \(g : \Jac(C) \to A\) such that \(f = g \circ \varphi_P\).  Milne's Proposition~6.1
100	  proves this under the standing hypothesis \(g(C)>0\), with \(P\) a \(k\)-rational point.
101	  The statement here includes genus zero; that case requires a separate argument and is not
102	  supplied by the cited proposition alone.
103	\end{theorem}

